INSERT INTO public.findit_challenges(challenge_id,name,description,active) VALUES ('C033','Something Disguised','Dress up or arrange an everyday object so it looks like something completely different.',true),('C034','Something in the Wrong Place','Put an everyday object somewhere unexpected but safe, and photograph the scene.',true),('C035','A Tiny World','Arrange household objects to create a miniature scene, such as a town, beach or alien planet.',true),('C036','An Impossible Size','Position objects near and far from the camera to make something small look enormous.',true),('C037','Objects Come Alive','Arrange everyday objects as characters doing something, such as having a meeting or playing a sport.',true) ON CONFLICT (challenge_id) DO NOTHING;